def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    prime_factors = set()
    for i in range(2, int(math.sqrt(a)) + 1):
        while a % i == 0:
            if is_prime(i):
                prime_factors.add(i)
            a //= i
    if a > 1 and is_prime(a):
        prime_factors.add(a)

    return len(prime_factors) == 3
